/**
 * Repository dossier — renders the real GitHub repositories that back the
 * Zazie Labs section: metadata, READMEs, file trees, commits, languages and
 * source-synced builds. Data comes from public/data/repos.json, generated by
 * scripts/sync-repos.mjs.
 */
import { marked } from 'marked';
import DOMPurify from 'dompurify';

marked.setOptions({ gfm: true, breaks: false });

const DATA_URL = 'data/repos.json';
const TABS = ['readme', 'files', 'commits', 'live'];

const state = {
  data: null,
  repo: null,
  tab: 'readme',
  treeCache: new Map(),
  fileCache: new Map(),
  currentDir: '',
  currentFile: null,
};

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));

const escapeHtml = (value = '') =>
  String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));

const number = (value) => new Intl.NumberFormat('en-US').format(Number(value) || 0);

function formatDate(value, { short = false } = {}) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '—';
  return date.toLocaleDateString('en-US', { year: 'numeric', month: short ? 'short' : 'long', day: 'numeric' });
}

function formatBytes(bytes) {
  if (!bytes && bytes !== 0) return '—';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function relativeTime(value) {
  if (!value) return '';
  const then = new Date(value).getTime();
  const diff = Date.now() - then;
  const units = [
    ['year', 31536000000],
    ['month', 2592000000],
    ['week', 604800000],
    ['day', 86400000],
    ['hour', 3600000],
    ['minute', 60000],
  ];
  for (const [unit, ms] of units) {
    const amount = Math.floor(diff / ms);
    if (amount >= 1) return `${amount} ${unit}${amount > 1 ? 's' : ''} ago`;
  }
  return 'just now';
}

function shortSha(sha) {
  return sha ? sha.slice(0, 7) : '—';
}

function slugify(text) {
  return String(text)
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .slice(0, 80);
}

const BINARY_EXTENSIONS = new Set([
  'png', 'jpg', 'jpeg', 'gif', 'webp', 'avif', 'bmp', 'ico', 'svg',
  'pdf', 'zip', 'tar', 'gz', '7z', 'rar',
  'mp3', 'wav', 'ogg', 'flac', 'm4a', 'aiff',
  'mp4', 'mov', 'webm', 'avi',
  'woff', 'woff2', 'ttf', 'otf', 'eot',
  'glb', 'gltf', 'wasm', 'bin', 'exe', 'dmg',
]);

const IMAGE_EXTENSIONS = new Set(['png', 'jpg', 'jpeg', 'gif', 'webp', 'avif', 'bmp', 'ico', 'svg']);
const extensionOf = (filePath) => (filePath.split('.').pop() || '').toLowerCase();

/* ------------------------------------------------------------------ */
/* README rendering                                                     */
/* ------------------------------------------------------------------ */

let readmeContext = { blobBase: '', rawBase: '' };
let readmeHooksInstalled = false;

function installReadmeHooks() {
  if (readmeHooksInstalled) return;
  readmeHooksInstalled = true;
  DOMPurify.addHook('afterSanitizeAttributes', (node) => {
    if (node.tagName === 'A') {
      const href = node.getAttribute('href');
      if (!href) return;
      if (href.startsWith('#')) return;
      const resolved = resolveUrl(href, readmeContext.blobBase);
      if (resolved) node.setAttribute('href', resolved);
      node.setAttribute('target', '_blank');
      node.setAttribute('rel', 'noopener noreferrer');
    }
    if (node.tagName === 'IMG') {
      const src = node.getAttribute('src');
      if (src) node.setAttribute('src', resolveUrl(src, readmeContext.rawBase) || src);
      node.setAttribute('loading', 'lazy');
      node.setAttribute('decoding', 'async');
      node.setAttribute('referrerpolicy', 'no-referrer');
      if (!node.getAttribute('alt')) node.setAttribute('alt', '');
    }
  });
}

function resolveUrl(value, base) {
  if (!value) return value;
  if (/^(?:https?:|mailto:|tel:)/i.test(value)) return value;
  if (value.startsWith('data:image/')) return value;
  if (value.startsWith('//')) return `https:${value}`;
  try {
    return new URL(value, base).href;
  } catch {
    return value;
  }
}

function renderReadme(repo) {
  installReadmeHooks();
  const readme = repo.readme;
  const meta = $('#readmeMeta');
  const body = $('#readmeBody');

  if (!readme) {
    meta.innerHTML = '<span>NO README FOUND IN THE DEFAULT BRANCH</span>';
    body.innerHTML = '<p class="text-mute">This repository does not expose a README through the GitHub API. Use the FILES tab to inspect the actual source tree.</p>';
    return;
  }

  const readmeDir = readme.path.includes('/') ? readme.path.slice(0, readme.path.lastIndexOf('/') + 1) : '';
  readmeContext = {
    blobBase: `${repo.url}/blob/${repo.defaultBranch}/${readmeDir}`,
    rawBase: `https://raw.githubusercontent.com/${repo.fullName}/${repo.defaultBranch}/${readmeDir}`,
  };

  meta.innerHTML = [
    `<span class="text-lime">${escapeHtml(readme.name || 'README.md')}</span>`,
    `<span>${escapeHtml(repo.fullName)}@${escapeHtml(repo.defaultBranch)}</span>`,
    readme.sha ? `<span>BLOB ${escapeHtml(shortSha(readme.sha))}</span>` : '',
    `<span>SYNCED ${escapeHtml(formatDate(state.data.generatedAt, { short: true }).toUpperCase())}</span>`,
    `<a href="https://raw.githubusercontent.com/${escapeHtml(repo.fullName)}/${escapeHtml(repo.defaultBranch)}/${escapeHtml(readme.path)}" target="_blank" rel="noopener noreferrer" class="text-lime hover:underline">RAW ↗</a>`,
  ].join('<span class="opacity-30">·</span>');

  let clean = '';
  try {
    const raw = marked.parse(readme.markdown || '');
    clean = DOMPurify.sanitize(raw, {
      ADD_ATTR: ['target', 'rel', 'align', 'width', 'height', 'colspan', 'rowspan', 'scope'],
      FORBID_TAGS: ['style', 'form', 'input', 'textarea', 'select', 'option', 'button', 'iframe', 'object', 'embed'],
      FORBID_ATTR: ['style', 'onerror', 'onload', 'onclick'],
      ALLOW_DATA_ATTR: false,
    });
  } catch (error) {
    clean = `<p class="text-mag">The markdown renderer could not parse this README (${escapeHtml(error.message)}). The source is shown below.</p><pre><code>${escapeHtml(readme.markdown || '')}</code></pre>`;
  }

  body.innerHTML = clean;
  body.querySelectorAll('a[href^="#"]').forEach((anchor) => {
    anchor.addEventListener('click', (event) => {
      const id = decodeURIComponent(anchor.getAttribute('href').slice(1));
      const target = document.getElementById(id);
      if (target) {
        event.preventDefault();
        target.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
      }
    });
  });
  // Give headings stable ids so README tables of contents work inside the page.
  body.querySelectorAll('h1, h2, h3, h4, h5, h6').forEach((heading) => {
    if (!heading.id) heading.id = slugify(heading.textContent || '');
  });
}

/* ------------------------------------------------------------------ */
/* Files                                                               */
/* ------------------------------------------------------------------ */

function rawFileUrl(repo, filePath) {
  return `https://raw.githubusercontent.com/${repo.fullName}/${repo.defaultBranch}/${filePath.split('/').map(encodeURIComponent).join('/')}`;
}

function githubBlobUrl(repo, filePath) {
  return `${repo.url}/blob/${repo.defaultBranch}/${filePath.split('/').map(encodeURIComponent).join('/')}`;
}

function renderTree(entries, dir) {
  const tree = $('#fileTree');
  const rows = [];
  if (dir) {
    const parent = dir.split('/').slice(0, -1).join('/');
    rows.push(
      `<button class="file-row text-mute" data-dir="${escapeHtml(parent)}" data-type="dir"><span class="w-4 text-center">↰</span><span class="truncate">..</span></button>`,
    );
  }
  for (const entry of entries) {
    const isDir = entry.type === 'dir';
    rows.push(
      `<button class="file-row" data-path="${escapeHtml(entry.path)}" data-dir="${escapeHtml(isDir ? entry.path : dir)}" data-type="${isDir ? 'dir' : 'file'}" title="${escapeHtml(entry.path)}">
        <span class="w-4 text-center ${isDir ? 'text-lime' : 'text-mute'}">${isDir ? '▸' : '◆'}</span>
        <span class="truncate ${isDir ? 'text-cream font-bold' : ''}">${escapeHtml(entry.name)}</span>
        ${isDir ? '' : `<span class="ml-auto pl-2 text-[9px] text-mute">${entry.size !== null ? escapeHtml(formatBytes(entry.size)) : ''}</span>`}
      </button>`,
    );
  }
  tree.innerHTML = rows.join('') || '<div class="p-4 font-mono text-[11px] text-mute">No files returned.</div>';
  const crumbs = dir ? dir.split('/') : [];
  $('#fileBreadcrumb').innerHTML =
    `<button class="hover:text-lime" data-dir="">${escapeHtml(state.repo.repo)}</button>` +
    crumbs.map((crumb, index) => {
      const target = crumbs.slice(0, index + 1).join('/');
      return `<span class="opacity-40">/</span><button class="hover:text-lime" data-dir="${escapeHtml(target)}">${escapeHtml(crumb)}</button>`;
    }).join('');
}

async function loadDirectory(dir = '') {
  const repo = state.repo;
  const cacheKey = dir || '/';
  if (state.treeCache.has(cacheKey)) {
    renderTree(state.treeCache.get(cacheKey), dir);
    state.currentDir = dir;
    return;
  }
  if (!dir) {
    state.treeCache.set('/', repo.tree);
    state.currentDir = '';
    renderTree(repo.tree, '');
    return;
  }
  $('#fileTree').innerHTML = '<div class="p-4 font-mono text-[11px] text-mute">Loading directory from GitHub…</div>';
  try {
    const url = `https://api.github.com/repos/${repo.fullName}/contents/${dir.split('/').map(encodeURIComponent).join('/')}?ref=${encodeURIComponent(repo.defaultBranch)}`;
    const response = await fetch(url, { headers: { Accept: 'application/vnd.github+json' } });
    if (!response.ok) throw new Error(`GitHub returned ${response.status}`);
    const payload = await response.json();
    if (!Array.isArray(payload)) throw new Error('Not a directory');
    const entries = payload
      .filter((entry) => entry && entry.name !== '.git')
      .map((entry) => ({ name: entry.name, path: entry.path, type: entry.type === 'dir' ? 'dir' : 'file', size: entry.size ?? null }))
      .sort((a, b) => (a.type === b.type ? a.name.localeCompare(b.name) : a.type === 'dir' ? -1 : 1));
    state.treeCache.set(cacheKey, entries);
    renderTree(entries, dir);
    state.currentDir = dir;
  } catch (error) {
    $('#fileTree').innerHTML = `<div class="p-4 font-mono text-[11px] text-mag">Could not load this directory live (${escapeHtml(error.message)}).<br><br><a class="text-lime underline" href="${escapeHtml(`${repo.url}/tree/${repo.defaultBranch}/${dir.split('/').map(encodeURIComponent).join('/')}`)}" target="_blank" rel="noopener noreferrer">Browse it on GitHub ↗</a></div>`;
  }
}

function renderFileSkeleton(name) {
  $('#fileViewer').innerHTML = `
    <div class="px-4 py-3 border-b border-white/10 font-mono text-[10px] text-mute flex items-center justify-between gap-2">
      <span class="truncate">${escapeHtml(name)}</span><span class="text-lime">FETCHING SOURCE…</span>
    </div>
    <div class="p-6 font-mono text-[11px] text-mute">Loading the actual file from the repository…</div>`;
}

async function fetchFileText(repo, filePath) {
  if (state.fileCache.has(filePath)) return state.fileCache.get(filePath);
  let text = null;
  let source = '';
  try {
    const response = await fetch(rawFileUrl(repo, filePath), { cache: 'no-cache' });
    if (response.ok) {
      text = await response.text();
      source = 'raw.githubusercontent.com';
    }
  } catch {
    /* fall through to the API */
  }
  if (text === null) {
    const apiUrl = `https://api.github.com/repos/${repo.fullName}/contents/${filePath.split('/').map(encodeURIComponent).join('/')}?ref=${encodeURIComponent(repo.defaultBranch)}`;
    const response = await fetch(apiUrl, { headers: { Accept: 'application/vnd.github+json' } });
    if (!response.ok) throw new Error(`GitHub returned ${response.status}`);
    const payload = await response.json();
    if (!payload || !payload.content) throw new Error('No text content returned');
    const binary = atob(payload.content.replace(/\n/g, ''));
    const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
    text = new TextDecoder('utf-8').decode(bytes);
    source = 'api.github.com';
  }
  const record = { text, source };
  state.fileCache.set(filePath, record);
  return record;
}

async function openFile(filePath) {
  const repo = state.repo;
  state.currentFile = filePath;
  $$('#fileTree .file-row').forEach((row) => row.classList.toggle('is-active', row.dataset.path === filePath));
  const extension = extensionOf(filePath);
  const entry = (state.treeCache.get(state.currentDir || '/') || []).find((item) => item.path === filePath);

  if (IMAGE_EXTENSIONS.has(extension)) {
    $('#fileViewer').innerHTML = `
      <div class="px-4 py-3 border-b border-white/10 font-mono text-[10px] text-mute flex flex-wrap items-center justify-between gap-2">
        <span class="truncate">${escapeHtml(filePath)}</span>
        <a href="${escapeHtml(githubBlobUrl(repo, filePath))}" target="_blank" rel="noopener noreferrer" class="text-lime hover:underline">OPEN SOURCE ↗</a>
      </div>
      <div class="p-4 flex items-center justify-center bg-[#07070b]">
        <img src="${escapeHtml(rawFileUrl(repo, filePath))}" alt="${escapeHtml(filePath)}" class="max-h-[440px] max-w-full rounded-xl border border-white/10 object-contain" loading="lazy" referrerpolicy="no-referrer">
      </div>
      <div class="px-4 pb-4 font-mono text-[10px] text-mute">IMAGE FILE${entry && entry.size !== null ? ` · ${escapeHtml(formatBytes(entry.size))}` : ''} · RENDERED FROM THE REPOSITORY</div>`;
    return;
  }

  if (BINARY_EXTENSIONS.has(extension)) {
    $('#fileViewer').innerHTML = `
      <div class="px-4 py-3 border-b border-white/10 font-mono text-[10px] text-mute">${escapeHtml(filePath)}</div>
      <div class="p-6 font-mono text-[11px] text-mute leading-relaxed">
        Binary or document file${entry && entry.size !== null ? ` · ${escapeHtml(formatBytes(entry.size))}` : ''}. It is not rendered inside the dossier.<br><br>
        <a class="text-lime underline" href="${escapeHtml(githubBlobUrl(repo, filePath))}" target="_blank" rel="noopener noreferrer">Open the file on GitHub ↗</a>
        <span class="px-2">·</span>
        <a class="text-lime underline" href="${escapeHtml(rawFileUrl(repo, filePath))}" target="_blank" rel="noopener noreferrer">Download raw ↗</a>
      </div>`;
    return;
  }

  if (entry && entry.size !== null && entry.size > 1_500_000) {
    $('#fileViewer').innerHTML = `
      <div class="px-4 py-3 border-b border-white/10 font-mono text-[10px] text-mute">${escapeHtml(filePath)}</div>
      <div class="p-6 font-mono text-[11px] text-mute leading-relaxed">This file is ${escapeHtml(formatBytes(entry.size))} — too large to render comfortably in the dossier.<br><br>
      <a class="text-lime underline" href="${escapeHtml(githubBlobUrl(repo, filePath))}" target="_blank" rel="noopener noreferrer">Read it on GitHub ↗</a></div>`;
    return;
  }

  renderFileSkeleton(filePath);
  try {
    const { text, source } = await fetchFileText(repo, filePath);
    const lines = text.split('\n');
    const capped = lines.slice(0, 4000);
    const truncated = lines.length > capped.length || text.length > 400_000;
    const code = capped.map((line) => `<span class="code-line">${escapeHtml(line) || ' '}</span>`).join('');
    $('#fileViewer').innerHTML = `
      <div class="px-4 py-3 border-b border-white/10 font-mono text-[10px] text-mute flex flex-wrap items-center justify-between gap-2">
        <span class="truncate">${escapeHtml(filePath)}</span>
        <span class="flex items-center gap-3">
          <span class="text-lime">${escapeHtml(source)}</span>
          <a href="${escapeHtml(githubBlobUrl(repo, filePath))}" target="_blank" rel="noopener noreferrer" class="hover:text-lime">SOURCE ↗</a>
        </span>
      </div>
      <div class="code-view max-h-[520px] overflow-auto"><pre><code>${code}</code></pre></div>
      ${truncated ? `<div class="px-4 py-2 font-mono text-[10px] text-mag border-t border-white/10">FILE TRUNCATED FOR THE DOSSIER — open the source for the complete file.</div>` : ''}`;
  } catch (error) {
    $('#fileViewer').innerHTML = `
      <div class="px-4 py-3 border-b border-white/10 font-mono text-[10px] text-mute">${escapeHtml(filePath)}</div>
      <div class="p-6 font-mono text-[11px] text-mag leading-relaxed">Could not fetch this file live (${escapeHtml(error.message)}).<br><br>
      <a class="text-lime underline" href="${escapeHtml(githubBlobUrl(repo, filePath))}" target="_blank" rel="noopener noreferrer">Read it on GitHub ↗</a></div>`;
  }
}

/* ------------------------------------------------------------------ */
/* Commits                                                             */
/* ------------------------------------------------------------------ */

function renderCommits(repo) {
  const list = $('#commitList');
  if (!repo.commits.length) {
    list.innerHTML = '<div class="p-6 font-mono text-[11px] text-mute">No commit history returned by the API.</div>';
    return;
  }
  list.innerHTML = repo.commits
    .map(
      (commit) => `
      <div class="p-4 md:p-5">
        <div class="flex flex-wrap items-start gap-3">
          <span class="chip text-lime border-lime/40 shrink-0">${escapeHtml(commit.shortSha)}</span>
          <div class="min-w-0 flex-1">
            <div class="font-bold text-[14px] leading-snug break-words">${escapeHtml(commit.message)}</div>
            <div class="font-mono text-[10px] text-mute mt-1">${escapeHtml(commit.author)} · ${escapeHtml(formatDate(commit.date))} · ${escapeHtml(relativeTime(commit.date))}</div>
          </div>
          <div class="flex gap-2 shrink-0">
            <button class="chip hover:border-lime" data-commit="${escapeHtml(commit.sha)}">FILES CHANGED</button>
            <a class="chip hover:border-lime" href="${escapeHtml(commit.url)}" target="_blank" rel="noopener noreferrer">COMMIT ↗</a>
          </div>
        </div>
        <div class="commit-files hidden mt-3" data-commit-files="${escapeHtml(commit.sha)}"></div>
      </div>`,
    )
    .join('');
}

async function toggleCommitFiles(sha) {
  const target = $(`[data-commit-files="${sha}"]`);
  if (!target) return;
  if (!target.classList.contains('hidden')) {
    target.classList.add('hidden');
    return;
  }
  target.classList.remove('hidden');
  if (target.dataset.loaded === 'true') return;
  target.innerHTML = '<div class="font-mono text-[10px] text-mute">Loading changed files from GitHub…</div>';
  try {
    const response = await fetch(`https://api.github.com/repos/${state.repo.fullName}/commits/${sha}`, {
      headers: { Accept: 'application/vnd.github+json' },
    });
    if (!response.ok) throw new Error(`GitHub returned ${response.status}`);
    const payload = await response.json();
    const files = payload.files || [];
    target.dataset.loaded = 'true';
    target.innerHTML = files.length
      ? `<div class="font-mono text-[9px] tracking-widest text-mute mb-2">${files.length} FILE${files.length === 1 ? '' : 'S'} CHANGED</div>
         <div class="space-y-1">${files.map((file) => `
           <div class="flex items-center gap-2 font-mono text-[10px]">
             <span class="text-mute w-12 shrink-0">${escapeHtml(file.status)}</span>
             <span class="truncate flex-1">${escapeHtml(file.filename)}</span>
             <span class="text-emerald-400">+${file.additions}</span>
             <span class="text-mag">−${file.deletions}</span>
           </div>`).join('')}</div>`
      : '<div class="font-mono text-[10px] text-mute">No file changes returned.</div>';
  } catch (error) {
    target.innerHTML = `<div class="font-mono text-[10px] text-mag">Could not load the diff (${escapeHtml(error.message)}). <a href="${escapeHtml(`https://github.com/${state.repo.fullName}/commit/${sha}`)}" target="_blank" rel="noopener noreferrer" class="text-lime underline">Open the commit ↗</a></div>`;
  }
}

/* ------------------------------------------------------------------ */
/* Live builds                                                         */
/* ------------------------------------------------------------------ */

function liveSource(repo) {
  if (repo.embed) return { kind: 'embedded', src: repo.embed.url, label: repo.embed.label || 'SOURCE-SYNCED BUILD' };
  if (repo.demoUrl) return { kind: 'external', src: repo.demoUrl, label: 'LIVE DEPLOYMENT' };
  return null;
}

function buildLiveToolbar(repo, live) {
  const toolbar = $('#liveToolbar');
  const stage = $('#liveStage');
  const note = $('#liveNote');
  const external = live.kind === 'external';
  toolbar.innerHTML = `
    <div class="flex items-center gap-2 min-w-0">
      <span class="w-2 h-2 rounded-full ${external ? 'bg-cy' : 'bg-lime'} pulse-dot shrink-0"></span>
      <span class="font-mono text-[10px] tracking-widest truncate">${escapeHtml(live.label)}</span>
      <span class="chip hidden sm:inline-block">${external ? 'EXTERNAL ORIGIN' : 'SAME-ORIGIN'}</span>
    </div>
    <div class="flex items-center gap-2">
      <button id="liveReload" class="chip hover:border-lime">RELOAD</button>
      <button id="liveFullscreen" class="chip hover:border-lime">FULLSCREEN</button>
      <a href="${escapeHtml(live.src)}" target="_blank" rel="noopener noreferrer" class="btn-lime rounded-lg px-3 py-2 font-mono text-[10px] font-bold">OPEN STANDALONE ↗</a>
    </div>`;
  stage.innerHTML = `
    <div class="relative">
      <div id="liveLoader" class="absolute inset-0 z-10 flex flex-col items-center justify-center gap-3 bg-[#05050a]">
        <div class="w-10 h-10 rounded-xl bg-lime text-black flex items-center justify-center font-bold spin-slow">◉</div>
        <div class="font-mono text-[10px] text-mute tracking-widest">STARTING ${escapeHtml(repo.displayName)}…</div>
      </div>
      <iframe id="liveFrame" title="${escapeHtml(repo.displayName)} — running repository build"
        class="w-full block bg-[#05050a]" style="height:70vh;min-height:520px"
        loading="lazy" allow="autoplay; fullscreen; midi; microphone; clipboard-write; gamepad"
        referrerpolicy="no-referrer"></iframe>
    </div>`;

  const frame = $('#liveFrame');
  const loader = $('#liveLoader');
  frame.addEventListener('load', () => loader?.remove(), { once: true });
  // Cross-origin frames that refuse to render never fire a useful error event.
  setTimeout(() => loader?.remove(), 15000);

  note.innerHTML = external
    ? `EXTERNAL APP SERVED FROM <a href="${escapeHtml(live.src)}" target="_blank" rel="noopener noreferrer" class="text-lime underline">${escapeHtml(new URL(live.src).host)}</a>. If the frame stays blank, the deployment may block embedding — use OPEN STANDALONE. Audio starts only after you interact with the app.`
    : `THIS IS THE PROJECT'S ACTUAL BUILD, COPIED VERBATIM FROM <span class="text-cream">${escapeHtml(repo.fullName)}@${escapeHtml(repo.defaultBranch)}</span> AND SERVED FROM THIS SITE. ${repo.embed ? `SOURCE FILE: <a href="${escapeHtml(repo.embed.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="text-lime underline">${escapeHtml(repo.embed.sourcePath)}</a> · ${escapeHtml(formatBytes(repo.embed.bytes))} · SYNCED ${escapeHtml(formatDate(repo.embed.syncedAt, { short: true }).toUpperCase())}.` : ''} Audio starts only after you interact.`;

  frame.src = live.src;

  $('#liveReload').addEventListener('click', () => {
    frame.src = 'about:blank';
    setTimeout(() => { frame.src = live.src; }, 60);
  });
  $('#liveFullscreen').addEventListener('click', async () => {
    const target = $('#liveStage');
    try {
      if (document.fullscreenElement) await document.exitFullscreen();
      else await target.requestFullscreen();
    } catch {
      /* fullscreen may be unavailable in embedded previews */
    }
  });
}

/* ------------------------------------------------------------------ */
/* Aside panels                                                        */
/* ------------------------------------------------------------------ */

function factRow(label, value) {
  return `<div class="flex items-start justify-between gap-3 py-1.5 border-b border-white/5 last:border-0">
    <dt class="font-mono text-[9px] tracking-widest text-mute shrink-0 pt-0.5">${escapeHtml(label)}</dt>
    <dd class="text-[11px] text-right min-w-0 break-words">${value}</dd>
  </div>`;
}

function renderFacts(repo) {
  const license = repo.license ? (repo.license.spdx && repo.license.spdx !== 'NOASSERTION' ? repo.license.spdx : repo.license.name) : 'None detected';
  const pages = repo.pages
    ? repo.pages.url
      ? `<a href="${escapeHtml(repo.pages.url)}" target="_blank" rel="noopener noreferrer" class="text-lime hover:underline">${escapeHtml(repo.pages.status || repo.pages.buildType || 'configured')} ↗</a>`
      : escapeHtml(repo.pages.status || 'configured')
    : 'Not configured';
  $('#factsPanel').innerHTML = `
    <div class="eyebrow text-lime mb-2">REPOSITORY FACTS</div>
    <dl>
      ${factRow('FULL NAME', `<a href="${escapeHtml(repo.url)}" target="_blank" rel="noopener noreferrer" class="hover:text-lime">${escapeHtml(repo.fullName)}</a>`)}
      ${factRow('BRANCH', `<code class="font-mono text-[11px] text-cream">${escapeHtml(repo.defaultBranch)}</code>`)}
      ${factRow('LANGUAGE', escapeHtml(repo.language || '—'))}
      ${factRow('LICENSE', escapeHtml(license))}
      ${factRow('STARS / FORKS', `${number(repo.stars)} / ${number(repo.forks)}`)}
      ${factRow('WATCHERS / ISSUES', `${number(repo.watchers)} / ${number(repo.openIssues)}`)}
      ${factRow('SIZE', repo.sizeKB !== null ? `${number(repo.sizeKB)} KB` : '—')}
      ${factRow('CREATED', escapeHtml(formatDate(repo.createdAt, { short: true })))}
      ${factRow('LAST PUSH', escapeHtml(formatDate(repo.pushedAt, { short: true })))}
      ${factRow('PAGES', pages)}
      ${factRow('VISIBILITY', `${escapeHtml(repo.visibility)}${repo.fork ? ' · fork' : ''}${repo.archived ? ' · archived' : ''}`)}
    </dl>
    ${repo.topics.length ? `<div class="flex flex-wrap gap-1.5 mt-3">${repo.topics.map((topic) => `<span class="chip text-[9px]">${escapeHtml(topic)}</span>`).join('')}</div>` : ''}`;
}

const CHART_COLORS = ['#e6ff4a', '#5cf2ff', '#8b7cff', '#ff3ea5', '#ffb347', '#7CFFB2', '#ff6b6b', '#a8a8c8'];

function renderTelemetry(repo) {
  const repos = state.data.repositories;
  const commits = [...(repo.commits || [])].filter((commit) => Number.isFinite(Date.parse(commit.date))).sort((a, b) => Date.parse(a.date) - Date.parse(b.date));
  const first = commits.length ? Date.parse(commits[0].date) : 0;
  const last = commits.length ? Date.parse(commits[commits.length - 1].date) : 0;
  const span = Math.max(last - first, 1);
  const points = commits.map((commit, index) => {
    const x = commits.length === 1 ? 200 : 24 + ((Date.parse(commit.date) - first) / span) * 352;
    const y = 30 + (index % 3) * 12;
    const date = formatDate(commit.date, { short: true });
    return `<circle cx="${x.toFixed(1)}" cy="${y}" r="5" fill="${CHART_COLORS[index % CHART_COLORS.length]}" stroke="#090910" stroke-width="2"><title>${escapeHtml(date)} · ${escapeHtml(commit.author)} · ${escapeHtml(commit.message)}</title></circle>`;
  }).join('');
  const activityPath = commits.length > 1
    ? `<polyline points="${commits.map((commit, index) => {
      const x = 24 + ((Date.parse(commit.date) - first) / span) * 352;
      return `${x.toFixed(1)},${30 + (index % 3) * 12}`;
    }).join(' ')}" fill="none" stroke="#5cf2ff" stroke-opacity=".45" stroke-width="2"/>`
    : '';
  const timeline = commits.length
    ? `<svg viewBox="0 0 400 112" class="telemetry-svg" role="img" aria-label="Timeline of the ${commits.length} most recent commits, oldest to newest"><defs><linearGradient id="activityGlow" x1="0" x2="1"><stop stop-color="#8b7cff"/><stop offset="1" stop-color="#5cf2ff"/></linearGradient></defs><path d="M24 76H376" stroke="rgba(255,255,255,.13)" stroke-dasharray="3 5"/>${activityPath}${points}<text x="24" y="99" class="chart-label">${escapeHtml(formatDate(commits[0].date, { short: true }))}</text><text x="376" y="99" text-anchor="end" class="chart-label">${escapeHtml(formatDate(commits[commits.length - 1].date, { short: true }))}</text><text x="200" y="108" text-anchor="middle" class="chart-label">OLDEST → NEWEST · RECENT ${commits.length}</text></svg>`
    : '<p class="text-[11px] text-mute">No dated commits in the current snapshot.</p>';
  const totalBytes = (repo.languages || []).reduce((sum, language) => sum + (Number(language.bytes) || 0), 0);
  let offset = 0;
  const segments = (repo.languages || []).map((language, index) => {
    const percent = Math.max(0, Math.min(100, Number(language.percent) || 0));
    const circumference = 263.89;
    const dash = (percent / 100) * circumference;
    const segment = `<circle cx="60" cy="60" r="42" fill="none" stroke="${CHART_COLORS[index % CHART_COLORS.length]}" stroke-width="13" stroke-dasharray="${dash} ${circumference - dash}" stroke-dashoffset="${-offset}" transform="rotate(-90 60 60)"><title>${escapeHtml(language.name)} · ${percent}%</title></circle>`;
    offset += dash;
    return segment;
  }).join('');
  const ring = totalBytes
    ? `<div class="language-ring-wrap"><svg viewBox="0 0 120 120" class="language-ring" role="img" aria-label="Source language composition by GitHub-reported bytes">${segments}<circle cx="60" cy="60" r="31" fill="#0e0e15"/><text x="60" y="57" text-anchor="middle" class="ring-value">${repo.languages.length}</text><text x="60" y="69" text-anchor="middle" class="ring-caption">LANGS</text></svg></div>`
    : '<div class="language-ring-empty">NO DATA</div>';
  const languageLegend = (repo.languages || []).slice(0, 5).map((language, index) => `<div class="viz-legend-row"><span class="viz-dot" style="background:${CHART_COLORS[index % CHART_COLORS.length]}"></span><span class="truncate">${escapeHtml(language.name)}</span><span class="font-mono text-[10px] text-mute">${Number(language.percent) || 0}%</span></div>`).join('');
  const metrics = [
    ['STARS', 'stars'], ['FORKS', 'forks'], ['OPEN ISSUES', 'openIssues'], ['REPO SIZE', 'sizeKB'], ['RECENT COMMITS', null],
  ];
  const comparisons = metrics.map(([label, key]) => {
    const value = key ? Number(repo[key]) || 0 : commits.length;
    const values = repos.map((item) => key ? Number(item[key]) || 0 : (item.commits || []).length);
    const max = Math.max(1, ...values);
    const percentile = Math.round((values.filter((item) => item <= value).length / Math.max(values.length, 1)) * 100);
    const width = Math.max(value > 0 ? 4 : 0, Math.round((value / max) * 100));
    return `<div class="peer-row"><div class="flex items-center justify-between gap-2 mb-1"><span class="font-mono text-[9px] tracking-widest text-mute">${label}</span><span class="font-mono text-[10px] text-cream">${number(value)} <span class="text-mute">· P${percentile}</span></span></div><div class="peer-track" role="img" aria-label="${label}: ${number(value)}, percentile ${percentile} among ${repos.length} curated repositories"><span style="width:${width}%"></span></div></div>`;
  }).join('');
  const dateRange = commits.length ? `${formatDate(commits[0].date, { short: true })} — ${formatDate(commits[commits.length - 1].date, { short: true })}` : 'NO DATED COMMITS';
  $('#repoTelemetry').innerHTML = `
    <article class="telemetry-card telemetry-activity">
      <div class="telemetry-card-head"><div><div class="eyebrow text-cy">01 / ACTIVITY TRACE</div><h2 class="telemetry-title">Commit signal</h2></div><span class="telemetry-mark">↗</span></div>
      <div class="telemetry-big">${number(commits.length)} <span>recent commits</span></div>
      ${timeline}
      <div class="telemetry-foot"><span>${escapeHtml(dateRange)}</span><span>DEFAULT BRANCH</span></div>
    </article>
    <article class="telemetry-card telemetry-language">
      <div class="telemetry-card-head"><div><div class="eyebrow text-lime">02 / SOURCE PROFILE</div><h2 class="telemetry-title">Language mix</h2></div><span class="telemetry-mark">◌</span></div>
      <div class="language-viz">${ring}<div class="language-legend">${languageLegend || '<span class="text-[11px] text-mute">No language breakdown</span>'}</div></div>
      <div class="telemetry-foot"><span>${number(totalBytes)} bytes indexed</span><span>GITHUB LANGUAGES API</span></div>
    </article>
    <article class="telemetry-card telemetry-peers">
      <div class="telemetry-card-head"><div><div class="eyebrow text-mag">03 / PORTFOLIO CONTEXT</div><h2 class="telemetry-title">Signal vs. atlas</h2></div><span class="telemetry-mark">◉</span></div>
      <div class="peer-chart">${comparisons}</div>
      <div class="telemetry-foot"><span>Percentile within ${repos.length} curated repos</span><span>LIVE SNAPSHOT</span></div>
    </article>`;
}

function renderLanguages(repo) {
  const total = repo.languages.reduce((sum, language) => sum + language.bytes, 0);
  $('#languagesPanel').innerHTML = `
    <div class="eyebrow text-cy mb-3">LANGUAGES</div>
    ${repo.languages.length
      ? `<div class="flex h-2 rounded-full overflow-hidden mb-3">${repo.languages.map((language, index) => `<span style="width:${language.percent}%;background:${['#e6ff4a', '#5cf2ff', '#8b7cff', '#ff3ea5', '#ffb347', '#7CFFB2', '#ff4444', '#9a9ab0'][index % 8]}"></span>`).join('')}</div>
         <div class="space-y-1.5">${repo.languages.map((language, index) => `<div class="flex items-center gap-2 text-[11px]"><span class="w-2 h-2 rounded-full shrink-0" style="background:${['#e6ff4a', '#5cf2ff', '#8b7cff', '#ff3ea5', '#ffb347', '#7CFFB2', '#ff4444', '#9a9ab0'][index % 8]}"></span><span class="flex-1 truncate">${escapeHtml(language.name)}</span><span class="font-mono text-[10px] text-mute">${language.percent}%</span></div>`).join('')}</div>
         <div class="font-mono text-[9px] text-mute mt-3">${number(total)} BYTES REPORTED BY GITHUB</div>`
      : '<div class="font-mono text-[11px] text-mute">No language breakdown returned.</div>'}`;
}

function renderDiligence(repo) {
  $('#diligencePanel').innerHTML = `
    <div class="eyebrow text-amber-300 mb-3">DILIGENCE NOTE</div>
    <div class="space-y-3 text-[11px] leading-relaxed">
      <div><div class="font-mono text-[9px] tracking-widest text-mute mb-1">POTENTIAL ROUTE</div><p class="text-mute">${escapeHtml(repo.potential)}</p></div>
      <div><div class="font-mono text-[9px] tracking-widest text-mute mb-1">RIGHTS SIGNAL</div><p class="text-mute">${escapeHtml(repo.rights)}</p></div>
      <div><div class="font-mono text-[9px] tracking-widest text-mute mb-1">STATUS</div><p class="text-mute">${escapeHtml(repo.status)}</p></div>
    </div>
    <p class="font-mono text-[9px] text-mute mt-4 border-t border-white/10 pt-3">Repository visibility is not a statement of ownership, exclusivity or commercial rights.</p>`;
}

function renderBuild(repo) {
  if (!repo.package) {
    $('#buildPanel').innerHTML = `
      <div class="eyebrow text-viol mb-2">BUILD</div>
      <p class="text-[11px] text-mute leading-relaxed">No <code class="text-cream">package.json</code> at the repository root. This is a static or non-Node project — the README is the runbook.</p>
      <a href="${escapeHtml(`${repo.url}/blob/${repo.defaultBranch}/README.md`)}" target="_blank" rel="noopener noreferrer" class="font-mono text-[10px] text-lime hover:underline inline-block mt-3">README QUICK START ↗</a>`;
    return;
  }
  const scripts = Object.entries(repo.package.scripts || {});
  $('#buildPanel').innerHTML = `
    <div class="eyebrow text-viol mb-2">BUILD MANIFEST</div>
    <div class="font-mono text-[10px] text-mute">${escapeHtml(repo.package.name || 'package.json')}${repo.package.version ? ` · v${escapeHtml(repo.package.version)}` : ''}</div>
    <div class="mt-3 space-y-1 font-mono text-[10px]">
      ${scripts.length ? scripts.slice(0, 8).map(([name, command]) => `<div class="flex gap-2"><span class="text-lime shrink-0">npm run ${escapeHtml(name)}</span><span class="text-mute truncate">${escapeHtml(command)}</span></div>`).join('') : '<div class="text-mute">No npm scripts declared.</div>'}
    </div>
    <div class="font-mono text-[9px] text-mute mt-3 border-t border-white/10 pt-3">${number(repo.package.dependencies)} runtime deps · ${number(repo.package.devDependencies)} dev deps</div>`;
}

function renderProvenance(repo) {
  if (!repo.embed) {
    $('#provenancePanel').innerHTML = `
      <div class="eyebrow text-mute mb-2">EMBED PROVENANCE</div>
      <p class="text-[11px] text-mute leading-relaxed">No vendored build. This dossier renders the repository itself — README, files and commits.</p>
      ${repo.demoUrl ? `<a href="${escapeHtml(repo.demoUrl)}" target="_blank" rel="noopener noreferrer" class="font-mono text-[10px] text-lime hover:underline inline-block mt-3">OPEN LIVE DEPLOYMENT ↗</a>` : ''}`;
    return;
  }
  $('#provenancePanel').innerHTML = `
    <div class="eyebrow text-lime mb-2">EMBED PROVENANCE</div>
    <dl>
      ${factRow('SOURCE FILE', `<a href="${escapeHtml(repo.embed.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="text-lime hover:underline break-all">${escapeHtml(repo.embed.sourcePath)}</a>`)}
      ${factRow('BYTES', escapeHtml(formatBytes(repo.embed.bytes)))}
      ${factRow('HEAD SHA', escapeHtml(shortSha(repo.embed.headSha)))}
      ${factRow('BLOB SHA', escapeHtml(shortSha(repo.embed.blobSha)))}
      ${factRow('SYNCED', escapeHtml(formatDate(repo.embed.syncedAt, { short: true })))}
    </dl>
    <a href="${escapeHtml(repo.embed.url.replace(/index\.html$/, 'PROVENANCE.txt'))}" target="_blank" rel="noopener noreferrer" class="font-mono text-[10px] text-lime hover:underline inline-block mt-3">PROVENANCE.TXT ↗</a>`;
}

function renderSwitcher(repo) {
  const groups = { sketch: 'CORE SKETCHES', candidate: 'ADDITIONAL CANDIDATES' };
  const options = Object.entries(groups).map(([section, label]) => `
    <optgroup label="${escapeHtml(label)}">
      ${state.data.repositories.filter((item) => item.section === section).map((item) => `<option value="${escapeHtml(item.id)}" ${item.id === repo.id ? 'selected' : ''}>${escapeHtml(item.displayName)}</option>`).join('')}
    </optgroup>`).join('');
  $('#switcherPanel').innerHTML = `
    <div class="eyebrow text-mute mb-3">SWITCH REPOSITORY</div>
    <select id="repoSelect" class="w-full px-3 py-2.5 text-[12px]">${options}</select>
    <a href="repo.html" class="font-mono text-[10px] text-lime hover:underline inline-block mt-3">OPEN THE REPOSITORY ATLAS →</a>`;
  $('#repoSelect').addEventListener('change', (event) => {
    location.href = `repo.html?id=${encodeURIComponent(event.target.value)}`;
  });
}

function renderPrevNext(repo) {
  const index = state.data.repositories.findIndex((item) => item.id === repo.id);
  const previous = state.data.repositories[index - 1];
  const next = state.data.repositories[index + 1];
  const card = (item, direction) => item
    ? `<a href="repo.html?id=${encodeURIComponent(item.id)}" class="card-line rounded-2xl bg-panel p-5 card-hover block">
        <div class="font-mono text-[9px] tracking-widest text-mute mb-1">${direction}</div>
        <div class="font-bold text-lg truncate">${escapeHtml(item.displayName)}</div>
        <div class="font-mono text-[10px] text-mute mt-1 truncate">${escapeHtml(item.category)}</div>
      </a>`
    : '<div class="hidden sm:block"></div>';
  $('#prevNext').innerHTML = `${card(previous, '← PREVIOUS')}${card(next, 'NEXT →')}`;
}

/* ------------------------------------------------------------------ */
/* Tabs                                                                */
/* ------------------------------------------------------------------ */

function setTab(name, { updateHash = true } = {}) {
  if (!state.repo) return;
  const live = liveSource(state.repo);
  if (name === 'live' && !live) name = 'readme';
  if (!TABS.includes(name)) name = 'readme';
  state.tab = name;

  $$('.repo-tab').forEach((tab) => {
    const selected = tab.dataset.tab === name;
    tab.setAttribute('aria-selected', selected ? 'true' : 'false');
    tab.tabIndex = selected ? 0 : -1;
  });
  $$('.repo-panel').forEach((panel) => panel.classList.toggle('hidden', panel.dataset.panel !== name));

  if (name === 'live') {
    const stage = $('#liveStage');
    if (stage && stage.dataset.built !== 'true') {
      buildLiveToolbar(state.repo, live);
      stage.dataset.built = 'true';
    }
  }

  if (updateHash) {
    try {
      history.replaceState(null, '', `${location.pathname}${location.search}#${name}`);
    } catch {
      /* file:// or sandboxed contexts */
    }
  }
}

function wireTabs() {
  $$('.repo-tab').forEach((tab) => {
    tab.addEventListener('click', () => setTab(tab.dataset.tab));
    tab.addEventListener('keydown', (event) => {
      if (!['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      const tabs = $$('.repo-tab').filter((item) => !item.classList.contains('hidden'));
      const current = tabs.indexOf(tab);
      let target = current;
      if (event.key === 'ArrowRight') target = (current + 1) % tabs.length;
      if (event.key === 'ArrowLeft') target = (current - 1 + tabs.length) % tabs.length;
      if (event.key === 'Home') target = 0;
      if (event.key === 'End') target = tabs.length - 1;
      tabs[target].focus();
      setTab(tabs[target].dataset.tab);
    });
  });
}

/* ------------------------------------------------------------------ */
/* Repository view                                                     */
/* ------------------------------------------------------------------ */

function renderRepo(repo) {
  state.repo = repo;
  state.currentDir = '';
  state.currentFile = null;
  state.treeCache.clear();
  state.fileCache.clear();

  document.title = `${repo.displayName} — repository dossier — Zazie Media Holdings`;
  $('#navGithub').href = `https://github.com/${state.data.account}`;
  $('#repoView').classList.remove('hidden');
  $('#catalogView').classList.add('hidden');

  $('#crumbName').textContent = repo.repo;
  $('#heroAccent').style.background = `linear-gradient(90deg, ${repo.accent}, transparent 80%)`;
  $('#heroChip').textContent = repo.category;
  $('#heroChip').style.color = repo.accent;
  $('#heroChip').style.borderColor = `${repo.accent}66`;
  const sectionChip = $('#heroSectionChip');
  sectionChip.textContent = repo.section === 'sketch' ? 'CORE SOFTWARE SKETCH' : 'CURATED CANDIDATE';
  sectionChip.className = `chip ${repo.section === 'sketch' ? 'text-lime border-lime/40' : 'text-mute'}`;

  $('#heroTitle').innerHTML = escapeHtml(repo.displayName);
  $('#heroDesc').textContent = repo.description || repo.summary;

  const live = liveSource(repo);
  const license = repo.license ? (repo.license.spdx && repo.license.spdx !== 'NOASSERTION' ? repo.license.spdx : repo.license.name) : 'No license';
  const stats = [
    ['STARS', number(repo.stars)],
    ['FORKS', number(repo.forks)],
    ['LICENSE', license],
    ['LANGUAGE', repo.language || '—'],
    ['LAST PUSH', formatDate(repo.pushedAt, { short: true })],
    ['SIZE', repo.sizeKB !== null ? `${number(repo.sizeKB)} KB` : '—'],
  ];
  $('#heroStats').innerHTML = stats
    .map(([label, value]) => `<div class="card-line rounded-xl bg-black/30 p-3"><div class="font-mono text-[9px] tracking-widest text-mute">${escapeHtml(label)}</div><div class="font-bold text-[13px] mt-0.5 truncate">${escapeHtml(value)}</div></div>`)
    .join('');

  const actions = [
    `<a href="${escapeHtml(repo.url)}" target="_blank" rel="noopener noreferrer" class="btn-ghost rounded-lg px-4 py-2.5 font-mono text-[11px]">GITHUB REPO ↗</a>`,
  ];
  if (live) {
    actions.unshift(`<button id="heroRun" class="btn-lime rounded-lg px-5 py-2.5 font-bold text-[12px]">▶ RUN ${live.kind === 'embedded' ? 'THE ACTUAL BUILD' : 'LIVE DEPLOYMENT'}</button>`);
  } else {
    actions.unshift(`<button id="heroReadme" class="btn-lime rounded-lg px-5 py-2.5 font-bold text-[12px]">READ THE ACTUAL README →</button>`);
  }
  if (repo.demoUrl && live.kind === 'embedded') {
    actions.push(`<a href="${escapeHtml(repo.demoUrl)}" target="_blank" rel="noopener noreferrer" class="btn-ghost rounded-lg px-4 py-2.5 font-mono text-[11px]">HOSTED DEPLOYMENT ↗</a>`);
  }
  $('#heroActions').innerHTML = actions.join('');

  $('#heroMeta').innerHTML = [
    `<span class="text-cream">${escapeHtml(repo.fullName)}</span>@${escapeHtml(repo.defaultBranch)}`,
    `SNAPSHOT ${escapeHtml(formatDate(state.data.generatedAt, { short: true }).toUpperCase())}`,
    live ? `${live.kind === 'embedded' ? 'SOURCE-SYNCED BUILD' : 'EXTERNAL DEPLOYMENT'} AVAILABLE` : 'SOURCE DOSSIER',
    `<a href="repo.html" class="text-lime hover:underline">ATLAS</a>`,
  ].join(' <span class="opacity-30">·</span> ');

  const stage = $('#liveStage');
  stage.dataset.built = '';
  stage.innerHTML = '';
  $('#liveToolbar').innerHTML = '';
  $('#liveNote').innerHTML = '';

  renderReadme(repo);
  state.treeCache.set('/', repo.tree);
  renderTree(repo.tree, '');
  renderCommits(repo);
  renderFacts(repo);
  renderTelemetry(repo);
  renderLanguages(repo);
  renderDiligence(repo);
  renderBuild(repo);
  renderProvenance(repo);
  renderSwitcher(repo);
  renderPrevNext(repo);

  const liveTab = $('#tab-live');
  if (live) {
    liveTab.classList.remove('hidden');
    liveTab.setAttribute('aria-hidden', 'false');
    liveTab.textContent = live.kind === 'embedded' ? 'RUN EMBEDDED BUILD' : 'RUN LIVE APP';
  } else {
    liveTab.classList.add('hidden');
    liveTab.setAttribute('aria-hidden', 'true');
    if ($('#liveStage').dataset.built) {
      $('#liveStage').dataset.built = '';
      $('#liveStage').innerHTML = '';
      $('#liveToolbar').innerHTML = '';
      $('#liveNote').innerHTML = '';
    }
  }

  $('#heroRun')?.addEventListener('click', () => setTab('live'));
  $('#heroReadme')?.addEventListener('click', () => setTab('readme'));

  const requested = (location.hash || '').replace('#', '');
  const initialTab = TABS.includes(requested) && (requested !== 'live' || live) ? requested : (live ? 'live' : 'readme');
  setTab(initialTab, { updateHash: false });

  wireTabs();
  wireFileTree();

  if (location.hash === '#live' && !live) {
    document.querySelector('#repoView')?.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
  }
}

function wireFileTree() {
  const tree = $('#fileTree');
  tree.addEventListener('click', (event) => {
    const row = event.target.closest('.file-row');
    if (row) {
      if (row.dataset.type === 'dir') loadDirectory(row.dataset.path);
      else openFile(row.dataset.path);
      return;
    }
    const crumb = event.target.closest('[data-dir]');
    if (crumb && !crumb.classList.contains('file-row')) loadDirectory(crumb.dataset.dir || '');
  });
  $('#fileBreadcrumb').addEventListener('click', (event) => {
    const button = event.target.closest('[data-dir]');
    if (button) loadDirectory(button.dataset.dir || '');
  });
  $('#commitList').addEventListener('click', (event) => {
    const button = event.target.closest('[data-commit]');
    if (button) toggleCommitFiles(button.dataset.commit);
  });
}

function renderCatalog(notice = '') {
  const data = state.data;
  $('#catalogView').classList.remove('hidden');
  $('#repoView').classList.add('hidden');
  document.title = 'Repository atlas — Zazie Media Holdings';
  $('#navGithub').href = data.accountUrl;
  $('#catalogSynced').textContent = formatDate(data.generatedAt);
  $('#footerSynced').textContent = `SYNCED ${formatDate(data.generatedAt, { short: true }).toUpperCase()}`;

  const runnableCount = data.repositories.filter((repo) => repo.embed || repo.demoUrl).length;
  $('#catalogCounts').innerHTML = [
    ['REPOS', data.counts.curated],
    ['READMES', data.counts.withReadme],
    ['RUNNABLE', runnableCount],
  ].map(([label, value]) => `<div class="card-line rounded-xl bg-panel px-3 py-2"><div class="text-xl font-bold text-lime">${escapeHtml(value)}</div><div class="text-[9px] text-mute tracking-widest">${escapeHtml(label)}</div></div>`).join('');

  const noticeHtml = notice
    ? `<div class="card-line rounded-xl bg-panel p-4 font-mono text-[11px] text-amber-300 md:col-span-2 xl:col-span-3">${escapeHtml(notice)}</div>`
    : '';

  $('#catalogGrid').innerHTML = noticeHtml + data.repositories.map((repo) => {
    const live = liveSource(repo);
    const badge = live
      ? `<span class="chip ${live.kind === 'embedded' ? 'text-lime border-lime/40' : 'text-cy border-cy/40'}">${live.kind === 'embedded' ? 'EMBEDDED BUILD' : 'LIVE DEPLOYMENT'}</span>`
      : '<span class="chip text-mute">SOURCE DOSSIER</span>';
    return `<a href="repo.html?id=${encodeURIComponent(repo.id)}" class="card-line rounded-2xl bg-panel p-6 card-hover block relative overflow-hidden">
      <span class="absolute inset-x-0 top-0 h-[2px]" style="background:${repo.accent}"></span>
      <div class="flex flex-wrap items-center gap-2 font-mono text-[9px] tracking-widest text-mute"><span style="color:${repo.accent}">${escapeHtml(repo.category)}</span>${badge}</div>
      <h2 class="font-bold text-2xl mt-2">${escapeHtml(repo.displayName)}</h2>
      <p class="text-sm text-mute leading-relaxed mt-2 line-clamp-3">${escapeHtml(repo.description || repo.summary)}</p>
      <div class="flex flex-wrap gap-x-3 gap-y-1 font-mono text-[10px] text-mute mt-4 border-t border-white/10 pt-3">
        <span>★ ${number(repo.stars)}</span><span>${escapeHtml(repo.language || '—')}</span>
        <span>${escapeHtml(repo.license ? (repo.license.spdx && repo.license.spdx !== 'NOASSERTION' ? repo.license.spdx : repo.license.name) : 'NO LICENSE')}</span>
        <span class="ml-auto">${escapeHtml(formatDate(repo.pushedAt, { short: true }))}</span>
      </div>
      <div class="font-mono text-[10px] text-lime mt-3">OPEN DOSSIER →</div>
    </a>`;
  }).join('');
}

/* ------------------------------------------------------------------ */
/* Boot                                                                */
/* ------------------------------------------------------------------ */

function showError(message) {
  $('#loading').classList.add('hidden');
  $('#errorView').classList.remove('hidden');
  $('#errorMessage').textContent = message;
}

async function init() {
  let data;
  try {
    const response = await fetch(DATA_URL, { cache: 'no-cache' });
    if (!response.ok) throw new Error(`The snapshot request returned HTTP ${response.status}.`);
    data = await response.json();
    if (!data || !Array.isArray(data.repositories) || !data.repositories.length) {
      throw new Error('The snapshot contains no repositories.');
    }
  } catch (error) {
    showError(`${error.message} Run the site from a local server (npm run dev) or rebuild the snapshot with npm run repos:sync.`);
    return;
  }

  state.data = data;
  $('#loading').classList.add('hidden');
  $('#shell').classList.remove('hidden');
  $('#footerSynced').textContent = `SYNCED ${formatDate(data.generatedAt, { short: true }).toUpperCase()}`;

  const params = new URLSearchParams(location.search);
  const id = params.get('id');
  if (!id) {
    renderCatalog();
    return;
  }
  const repo = data.repositories.find((item) => item.id === id);
  if (!repo) {
    renderCatalog(`Repository "${id}" is not in the curated atlas. Pick one below.`);
    return;
  }
  renderRepo(repo);
}

window.addEventListener('DOMContentLoaded', init);
